#!/usr/bin/env python3
# vmp_recon.py — stage 2 静态侦察
# usage: python vmp_recon.py sample.exe [baseline.json]
# 产出: sample.exe.recon.json  — 为 stage 3 (x64dbg dump) 提供断点清单和 OEP 候选

import struct, sys, json, re

def rva2off_factory(sections):
    def rva2off(rva, size=1):
        for s in sections:
            va, vsz, raw, rsz = int(s['va'],16), int(s['vsz'],16), int(s['raw'],16), int(s['rsz'],16)
            if va <= rva < va + max(vsz, rsz):
                o = raw + (rva - va)
                if o < len(raw) or True:
                    return o
        return None
    return rva2off

def read_pe(data):
    e = struct.unpack_from('<I', data, 0x3C)[0]
    coff = e + 4
    machine, nsec, ts, _, _, opt_size, _ = struct.unpack_from('<HHIIIHH', data, coff)
    opt = coff + 20
    pe64 = struct.unpack_from('<H', data, opt)[0] == 0x20B
    entry = struct.unpack_from('<I', data, opt+16)[0]
    if pe64:
        image_base = struct.unpack_from('<Q', data, opt+24)[0]
        dd_off, sec_off = opt + 112, opt + opt_size
    else:
        image_base = struct.unpack_from('<I', data, opt+28)[0]
        dd_off, sec_off = opt + 96, opt + opt_size
    sections = []
    for i in range(nsec):
        s = sec_off + i*40
        name = data[s:s+8].rstrip(b'\0').decode('latin1')
        vsz, va, rsz, raw = struct.unpack_from('<IIII', data, s+8)
        chars = struct.unpack_from('<I', data, s+36)[0]
        sections.append(dict(name=name, va=hex(va), vsz=hex(vsz), raw=hex(raw),
                             rsz=hex(rsz), chars=hex(chars), _va=va, _vsz=vsz,
                             _raw=raw, _rsz=rsz))
    dds = {}
    for i, nm in enumerate(['export','import','resource','exception','security',
                            'basereloc','debug','arch','globalptr','tls','loadconfig',
                            'boundimport','iat','delayimport','clr','reserved']):
        rva, sz = struct.unpack_from('<II', data, dd_off + i*8)
        if rva or sz:
            dds[nm] = (rva, sz)
    return dict(pe64=pe64, entry=entry, image_base=image_base,
                sections=sections, dds=dds)

# ---------- 1. TLS 回调扫描 ----------
def scan_tls(data, pe, rva2off):
    """VMP 3.x 常把自解密第一跳挂在 TLS callback 上"""
    out = {'present': False, 'callbacks': [], 'raw_dir': None}
    if 'tls' not in pe['dds']:
        return out
    out['present'] = True
    rva, sz = pe['dds']['tls']
    o = rva2off(rva)
    out['raw_dir'] = data[o:o+sz].hex()
    if pe['pe64']:
        cb_rva, cb_end = struct.unpack_from('<QQ', data, o+8)
        addr_idx = struct.unpack_from('<Q', data, o+56)[0]
    else:
        cb_rva, cb_end = struct.unpack_from('<II', data, o+4)
        addr_idx = struct.unpack_from('<I', data, o+36)[0]
    # callback 数组: [fnptr, ..., 0]
    if cb_rva:
        co = rva2off(cb_rva - 0 if False else cb_rva)  # RVA already
        # TLS 目录里存的是 VA (image_base+rva) — 修正:
        cb_off = rva2off((cb_rva & 0xFFFFFFFF) - pe['image_base'] if cb_rva > pe['image_base'] else cb_rva)
        if cb_off is None:
            # 直接按 VA->RVA
            cb_off = rva2off(cb_rva - pe['image_base']) if cb_rva >= pe['image_base'] else None
        if cb_off is not None:
            i = 0
            while True:
                if pe['pe64']:
                    fn = struct.unpack_from('<Q', data, cb_off + i*8)[0]
                else:
                    fn = struct.unpack_from('<I', data, cb_off + i*4)[0]
                if fn == 0: break
                out['callbacks'].append(hex(fn))
                i += 1
                if i > 16: break
    return out

# ---------- 2. .pdata / SEH 异常链 ----------
def scan_exceptions(data, pe, rva2off):
    """VMP 用异常处理做反调试和控制流混淆 — runtime_function 表"""
    out = {'count': 0, 'entries': []}
    if 'exception' not in pe['dds']:
        return out
    rva, sz = pe['dds']['exception']
    o = rva2off(rva)
    if o is None:
        return out
    n = sz // 12  # RUNTIME_FUNCTION = 12 bytes (x64)
    out['count'] = n
    for i in range(min(n, 32)):
        begin, end, unwind = struct.unpack_from('<III', data, o + i*12)
        out['entries'].append(dict(begin=hex(begin), end=hex(end), unwind=hex(unwind)))
    return out

# ---------- 3. VMP 变体签名 (handler 表特征) ----------
def identify_variant(data, pe, rva2off):
    """VMP 3.x 各小版本 handler 分布不同 — 用已知字节模式区分"""
    sigs = {
        # (name, pattern, note)
        'vmp3_generic':   (b'VMProtect', '嵌入字符串 — 试用版常见'),
        'vm_start_mnem':  (b'\x48\x8B\x05', 'mov rax,[rip+..] — vm_entry 常见前导'),
        'vmp_mutate_jit': (b'\x4D\x8B\x33', 'mov r14,[r11] — 3.x bytecode fetch'),
    }
    hits = {}
    for name, (pat, note) in sigs.items():
        idx, found = 0, []
        while True:
            i = data.find(pat, idx)
            if i == -1: break
            found.append(hex(i))
            idx = i + 1
            if len(found) > 8: break
        if found:
            hits[name] = {'offsets': found, 'note': note}
    # .vmp0/.vmp1 节的 entropy（高熵=字节码/加密数据）
    ent = {}
    for s in pe['sections']:
        if '.vmp' in s['name']:
            raw, rsz = int(s['raw'],16), int(s['rsz'],16)
            blob = data[raw:raw+rsz]
            if blob:
                from math import log2
                freq = [0]*256
                for b in blob: freq[b] += 1
                e = -sum((c/len(blob))*log2(c/len(blob)) for c in freq if c)
                ent[s['name']] = round(e, 3)
    return {'signature_hits': hits, 'section_entropy': ent}

